def lfp_iterate(phi, bottom, eq_fn, max_iter=1000):
    L = bottom
    for _ in range(max_iter):
        L_new = phi(L)
        if eq_fn(L_new, L):
            return L
        L = L_new
    return L

def select_minimal(all_elements, phi, complexity):
    fps = [L for L in all_elements if phi(L) == L]
    return min(fps, key=complexity)

def compose_sim(sim_S, sim_T):
    def composed(a, b):
        t = sim_T(a, b)
        return sim_S(t, t)
    return composed
